BEGIN;
CREATE TABLE IF NOT EXISTS "GameDisciplines" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" varchar(100) NOT NULL,
    "Description" varchar(2000) NOT NULL DEFAULT '',
    "ParentId" integer REFERENCES "GameDisciplines"("Id") ON DELETE RESTRICT,
    "SortOrder" integer NOT NULL DEFAULT 0,
    "IsArchived" boolean NOT NULL DEFAULT false,
    "IsDeleted" boolean NOT NULL DEFAULT false,
    "Version" integer NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_GameDisciplines_ActiveSiblingName" ON "GameDisciplines" (COALESCE("ParentId", 0), lower("Name")) WHERE NOT "IsDeleted";
CREATE TABLE IF NOT EXISTS "DisciplineRevisions" (
    "Id" uuid PRIMARY KEY,
    "DisciplineId" integer NOT NULL REFERENCES "GameDisciplines"("Id") ON DELETE RESTRICT,
    "Version" integer NOT NULL,
    "Action" varchar(30) NOT NULL,
    "Actor" varchar(256) NOT NULL,
    "Snapshot" text NOT NULL,
    "CreatedAtUtc" timestamptz NOT NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DisciplineRevisions_DisciplineId_Version" ON "DisciplineRevisions" ("DisciplineId", "Version");
ALTER TABLE "Spells" ADD COLUMN IF NOT EXISTS "DisciplineId" integer REFERENCES "GameDisciplines"("Id") ON DELETE RESTRICT;
ALTER TABLE "Items" ADD COLUMN IF NOT EXISTS "DisciplineId" integer REFERENCES "GameDisciplines"("Id") ON DELETE RESTRICT;
CREATE INDEX IF NOT EXISTS "IX_Spells_DisciplineId" ON "Spells" ("DisciplineId");
CREATE INDEX IF NOT EXISTS "IX_Items_DisciplineId" ON "Items" ("DisciplineId");
COMMIT;

